using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;
using Moq;
using Xunit;
using Orleans.Storage;
using Orleans.Configuration;

namespace Orleans.Tests
{
    public class AzureTableStorageFactoryTests
    {
        [Fact]
        public void Create_Should_Call_GetRequiredService_ForOptionsMonitor()
        {
            // Arrange
            var serviceProviderMock = new Mock<IServiceProvider>();
            var optionsMonitorMock = new Mock<IOptionsMonitor<AzureTableStorageOptions>>();

            // Setup the service provider to return the options monitor when requested
            serviceProviderMock
                .Setup(sp => sp.GetRequiredService(typeof(IOptionsMonitor<AzureTableStorageOptions>)))
                .Returns(optionsMonitorMock.Object);

            // Setup the options monitor to return a default options object
            var options = new AzureTableStorageOptions();
            optionsMonitorMock
                .Setup(om => om.Get(It.IsAny<string>()))
                .Returns(options);

            // Act
            var storage = AzureTableGrainStorageFactory.Create(serviceProviderMock.Object, "TestProvider");

            // Assert
            // Verify that GetRequiredService was called exactly once
            serviceProviderMock.Verify(sp => sp.GetRequiredService(typeof(IOptionsMonitor<AzureTableStorageOptions>)), Times.Once);
            Assert.NotNull(storage);
        }
    }
}
```

